CREATE OR REPLACE FUNCTION public.check_face_duplicate(_student_id uuid,_descriptors jsonb,_threshold real DEFAULT 0.42) RETURNS TABLE(match_student_id uuid,match_code text,match_name text,min_distance real) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE elem jsonb; probe real[]; best_id uuid; best_dist real:=1e9; r record; dist real; BEGIN IF COALESCE(auth.role(),'')<>'service_role' AND NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director') OR public.has_role(auth.uid(),'teacher')) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF _descriptors IS NULL OR jsonb_typeof(_descriptors)<>'array' THEN RAISE EXCEPTION 'Invalid descriptors'; END IF; FOR elem IN SELECT value FROM jsonb_array_elements(_descriptors) LOOP SELECT array_agg(v::real ORDER BY ord) INTO probe FROM jsonb_array_elements_text(elem) WITH ORDINALITY AS t(v,ord); IF array_length(probe,1)=512 THEN FOR r IN SELECT d.student_id,d.descriptor FROM public.student_face_descriptors d WHERE d.student_id IS DISTINCT FROM _student_id AND array_length(d.descriptor,1)=512 LOOP SELECT 1-sum(a::double precision*b::double precision)/NULLIF(sqrt(sum(a::double precision*a::double precision)*sum(b::double precision*b::double precision)),0) INTO dist FROM unnest(probe,r.descriptor::real[]) AS pairs(a,b); IF dist IS NOT NULL AND dist<best_dist THEN best_dist:=dist;best_id:=r.student_id;END IF; END LOOP; ELSIF array_length(probe,1)=128 THEN SELECT d.student_id,public.face_distance(d.descriptor::real[],probe) AS distance INTO r FROM public.student_face_descriptors d WHERE d.student_id IS DISTINCT FROM _student_id AND array_length(d.descriptor,1)=128 ORDER BY 2 LIMIT 1; IF r.student_id IS NOT NULL AND r.distance<best_dist THEN best_dist:=r.distance;best_id:=r.student_id;END IF; ELSE RAISE EXCEPTION 'Invalid descriptor dimension'; END IF; END LOOP; IF best_id IS NOT NULL AND best_dist<=LEAST(COALESCE(_threshold,0.42),0.42) THEN RETURN QUERY SELECT s.id,s.student_code,btrim(concat_ws(' ',concat(coalesce(s.prefix,''),s.first_name),s.last_name)),best_dist FROM public.students s WHERE s.id=best_id; END IF; END; $$; REVOKE ALL ON FUNCTION public.check_face_duplicate(uuid,jsonb,real) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.check_face_duplicate(uuid,jsonb,real) TO authenticated,service_role;